-- Rich onboarding sample extras for the mystery workspace.
PRAGMA foreign_keys = ON;
UPDATE projects SET pov='三人称限定視点（音無律）', tense='過去形', style_guide='観察と推理を簡潔に書く。事実、証言、推測を段落内で混同しない。手がかりは解決前に一度以上提示し、比喩は音・時計・海霧のモチーフへ寄せる。', outline='三部構成の本格推理。第一部で嵐の館、遺言、鳴らないはずの鐘、密室死を提示。第二部で回想・証言・物証を分解し、犯行時刻の十五分のずれを特定。第三部で蓄音機の蝋管と青磁のカップから、入室前の毒殺と偽の零時を再構成する。', target_readers='フェアプレイ型の本格推理、館もの、複数の嘘が交差する証言劇を好む読者。', phase_resolution_mode='reading' WHERE id='default-project';
UPDATE tree_nodes SET intent='嵐で閉ざされた館と『今夜、鐘は鳴らない』という不能条件を提示する。', pov_character_id='sample-codex-ritsu', location_id='sample-codex-manor', chronicle_start_time=305, chronicle_start_minute=1085, chronicle_start_granularity='time', chronicle_precision='exact' WHERE id='sample-scene-1';
UPDATE tree_nodes SET intent='被害者専用の青磁のカップ、遺言変更、各容疑者の利害を自然な夕食場面に置く。', pov_character_id='sample-codex-ritsu', location_id='sample-codex-manor', chronicle_start_time=305, chronicle_start_minute=1200, chronicle_start_granularity='time', chronicle_precision='exact' WHERE id='sample-scene-2';
UPDATE tree_nodes SET intent='密室死と十一時五十分の鐘を提示し、読者に零時以後の犯行だと思わせる。', pov_character_id='sample-codex-ritsu', location_id='sample-codex-tower', chronicle_start_time=306, chronicle_start_minute=10, chronicle_start_granularity='time', chronicle_precision='exact' WHERE id='sample-scene-3';
UPDATE tree_nodes SET intent='死体発見前の人物配置を示し、澪と三枝がそれぞれ別の理由で嘘をつく余地を作る。', pov_character_id='sample-codex-ritsu', location_id='sample-codex-manor', chronicle_start_time=305, chronicle_start_minute=1420, chronicle_start_granularity='time', chronicle_precision='exact' WHERE id='sample-scene-4';
UPDATE tree_nodes SET intent='密室を脱出経路の問題から、入室前の摂取物の問題へ反転させる。', pov_character_id='sample-codex-ritsu', location_id='sample-codex-tower', chronicle_start_time=306, chronicle_start_minute=540, chronicle_start_granularity='time', chronicle_precision='exact' WHERE id='sample-scene-5';
UPDATE tree_nodes SET intent='四人の証言をBeatで分け、嘘の対象が場所・責任・過去・時刻で異なると示す。', pov_character_id='sample-codex-ritsu', location_id='sample-codex-manor', chronicle_start_time=306, chronicle_start_minute=660, chronicle_start_granularity='time', chronicle_precision='exact' WHERE id='sample-scene-6';
UPDATE tree_nodes SET intent='物の移動順から偽の鐘と実際の死亡時刻を再構成する。', pov_character_id='sample-codex-ritsu', location_id='sample-codex-manor', chronicle_start_time=306, chronicle_start_minute=900, chronicle_start_granularity='time', chronicle_precision='exact' WHERE id='sample-scene-7';
UPDATE tree_nodes SET intent='全ての主要手がかりを回収し、毒殺・密室・時刻偽装を一つの解答へ統合する。', pov_character_id='sample-codex-ritsu', location_id='sample-codex-manor', chronicle_start_time=306, chronicle_start_minute=1200, chronicle_start_granularity='time', chronicle_precision='exact' WHERE id='sample-scene-8';
UPDATE tree_nodes SET context_mode='suppress', aliases='["機能ガイド","サンプルガイド"]', excluded_aliases='[]' WHERE id='sample-note-guide';
UPDATE tree_nodes SET context_mode='mentioned', aliases='["犯行時刻メモ","捜査メモ"]', excluded_aliases='[]' WHERE id='sample-note-case';
UPDATE tree_nodes SET placed_beat_preview='["律が館へ到着。『今夜、鐘は鳴らない』という物理条件を最初に提示し、嵐で外部と隔絶された状況を作る。"]' WHERE id='sample-scene-1';
UPDATE tree_nodes SET placed_beat_preview='["澪の証言：場所の嘘","椿の証言：薬品管理の嘘","真帆の証言：食器と鐘の手順","三枝の証言：時刻の嘘"]' WHERE id='sample-scene-6';
UPDATE tree_nodes SET unplaced_beats_doc='[{"id":"sample-unplaced-1","beatType":"summary","pov":"sample-codex-ritsu","collapsed":false,"content":[{"type":"text","text":"食器、蝋管、人物の移動を一枚の時系列表へ並べる。"}]},{"id":"sample-unplaced-2","beatType":"guided","pov":"sample-codex-ritsu","collapsed":false,"content":[{"type":"text","text":"十一時四十七分の時計と十一時五十分の鐘の矛盾を言語化する。"}]},{"id":"sample-unplaced-3","beatType":"dialogue","pov":"sample-codex-toma","collapsed":false,"content":[{"type":"text","text":"三枝に鐘の方向をもう一度説明させ、他の証言との差を示す。"}]},{"id":"sample-unplaced-4","beatType":"setting","pov":null,"collapsed":false,"content":[{"type":"text","text":"温室の散水時計と蓄音機を確認する。雨音で小さな作動音が消える。"}]},{"id":"sample-unplaced-5","beatType":"micro","pov":null,"collapsed":false,"content":[{"type":"text","text":"律が一章の手帳『今夜、鐘は鳴らない』へ戻る。"}]}]', unplaced_beat_preview='["食器、蝋管、人物の移動を一枚の時系列表へ並べる。","十一時四十七分の時計と十一時五十分の鐘の矛盾を言語化する。","三枝に鐘の方向をもう一度説明させ、他の証言との差を示す。","温室の散水時計と蓄音機を確認する。雨音で小さな作動音が消える。","律が一章の手帳『今夜、鐘は鳴らない』へ戻る。"]' WHERE id='sample-scene-7';
INSERT INTO tree_nodes (id, project_id, parent_id, node_type, title, synopsis, sort_order, status, content, pov_character_id, location_id, char_count, archived_at, created_at, updated_at) VALUES ('sample-scene-archived', 'default-project', 'sample-folder-notes', 'scene', '（アーカイブ）温室の足跡', '犯人の脱出経路を示す案だったが、入室前の毒殺という解答を弱めるため没にした。', 'z9', 'draft', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"温室の濡れた床に一人分の足跡を置く案。密室からの脱出を示すように見えるが、解答の中心と競合するため削除した。"}]}]}', 'sample-codex-ritsu', 'sample-codex-greenhouse', 54, strftime('%Y-%m-%dT%H:%M:%fZ','now','-3 day'), strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'));
