INSERT INTO map_stickies (id, board_id, title, body, preview_text, palette_id, color_slot, ai_derived, created_at, updated_at) VALUES ('sample-map-sticky-1', 'default-project-main-board', '中心仮説', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"鐘の音は時刻ではなく、時刻を信じさせる演出。音源と実際の鐘を分ける。"}]}]}', '鐘の音は時刻ではない', 'post-it-playful', 0, 0, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT INTO map_stickies (id, board_id, title, body, preview_text, palette_id, color_slot, ai_derived, created_at, updated_at) VALUES ('sample-map-sticky-2', 'default-project-main-board', '証言の分類', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"容疑者の嘘を一枚ずつ分ける：澪＝場所、椿＝責任、真帆＝過去、三枝＝時刻。"}]}]}', '四人の嘘を分ける', 'post-it-playful', 2, 0, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT INTO map_ai_branches (id, board_id, prompt, seed_node_ids, session_id, model, token_usage, created_at, updated_at) VALUES ('sample-map-ai-branch', 'default-project-main-board', '三枝が鐘の音の方向を言い切る台詞を、露骨にしすぎず公平な手がかりにする案を三つ。', '["codex:sample-codex-toma","scene:sample-scene-3"]', 'sample-session-2', 'anthropic/claude-sonnet-4.6', 286, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'));
